def _tuple_to_dict(t):
    """Convert a tuple of (major, minor, patch, prerelease, build) to dict."""
    if not isinstance(t, tuple):
        raise TypeError("Expected tuple for comparison")
    major, minor, patch = t[0], t[1], t[2]
    prerelease = t[3] if len(t) > 3 else None
    build = t[4] if len(t) > 4 else None
    return {'major': int(major), 'minor': int(minor), 'patch': int(patch),
            'prerelease': str(prerelease) if prerelease is not None else None,
            'build': str(build) if build is not None else None}


